-- PMIN : Ingestion COMTRADE exportations mineraux

SELECT id, 'COMTRADE_MINERALS', 'COMTRADE Minerals exports', 'https://comtradeplus.un.org', 'csv', 'Exportations mineraux critiques HS26 HS71 HS27 2010-2024', true
FROM collect.data_providers WHERE code = 'WB'
ON CONFLICT (endpoint_code) DO NOTHING;

VALUES ('MIN_EXP_PRC', 'Exportations mineraux PRC', 'Mineral exports PRC', 'PMIN', '+', 'USD', 'STANDARD')
ON CONFLICT (code) DO NOTHING;

VALUES ('MIN_EXP_ORE', 'Exportations mineraux ORE', 'Mineral exports ORE', 'PMIN', '+', 'USD', 'STANDARD')
ON CONFLICT (code) DO NOTHING;

VALUES ('MIN_EXP_FUL', 'Exportations mineraux FUL', 'Mineral exports FUL', 'PMIN', '+', 'USD', 'STANDARD')
ON CONFLICT (code) DO NOTHING;

